/**
 * Independent copper spacing check. Recomputes, from geometry alone, the smallest gap between
 * copper of different nets on each layer (trace segments, SMD pads, vias and plated holes).
 * It does not trust the router's own DRC: this is the second opinion.
 *
 * Copper pours are not included (their clearance is generated by construction).
 */

export interface ClearanceViolation {
  gapMm: number
  layer: string
  a: string
  b: string
  at: { x: number; y: number }
}

export interface ClearanceResult {
  /** Smallest different-net gap found, mm; null when the board has fewer than two nets of copper */
  minGapMm: number | null
  pairsChecked: number
  violations: ClearanceViolation[]
}

type Pt = { x: number; y: number }
/** A copper shape: a thick segment (capsule) or an axis-aligned rectangle. */
type Shape =
  | { kind: "seg"; a: Pt; b: Pt; r: number; net: string; layer: string; label: string; through?: string }
  | { kind: "rect"; cx: number; cy: number; hw: number; hh: number; net: string; layer: string; label: string; through?: string }

const dist = (p: Pt, q: Pt) => Math.hypot(p.x - q.x, p.y - q.y)

/** A w x h pad rotated by `deg`, as a capsule along its long axis (exact for circles and slotted pads). */
function capsule(cx: number, cy: number, w: number, h: number, deg: number, rest: { net: string; layer: string; label: string; through?: string }): Shape {
  const long = Math.max(w, h)
  const short = Math.min(w, h)
  const angle = ((w >= h ? deg : deg + 90) * Math.PI) / 180
  const half = (long - short) / 2
  const dx = Math.cos(angle) * half
  const dy = Math.sin(angle) * half
  return { kind: "seg", a: { x: cx - dx, y: cy - dy }, b: { x: cx + dx, y: cy + dy }, r: short / 2, ...rest }
}

function pointSeg(p: Pt, a: Pt, b: Pt): number {
  const dx = b.x - a.x
  const dy = b.y - a.y
  const len2 = dx * dx + dy * dy
  if (len2 === 0) return dist(p, a)
  const t = Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2))
  return dist(p, { x: a.x + t * dx, y: a.y + t * dy })
}

function segsIntersect(a: Pt, b: Pt, c: Pt, d: Pt): boolean {
  const o = (p: Pt, q: Pt, r: Pt) => Math.sign((q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x))
  const o1 = o(a, b, c)
  const o2 = o(a, b, d)
  const o3 = o(c, d, a)
  const o4 = o(c, d, b)
  return o1 !== o2 && o3 !== o4 && !(o1 === 0 && o2 === 0)
}

function segSeg(a: Pt, b: Pt, c: Pt, d: Pt): number {
  if (segsIntersect(a, b, c, d)) return 0
  return Math.min(pointSeg(a, c, d), pointSeg(b, c, d), pointSeg(c, a, b), pointSeg(d, a, b))
}

function rectCorners(r: Extract<Shape, { kind: "rect" }>): Pt[] {
  return [
    { x: r.cx - r.hw, y: r.cy - r.hh },
    { x: r.cx + r.hw, y: r.cy - r.hh },
    { x: r.cx + r.hw, y: r.cy + r.hh },
    { x: r.cx - r.hw, y: r.cy + r.hh },
  ]
}

const inRect = (p: Pt, r: Extract<Shape, { kind: "rect" }>) => Math.abs(p.x - r.cx) <= r.hw && Math.abs(p.y - r.cy) <= r.hh

/** Edge-to-edge gap between two copper shapes (0 or negative means they touch or overlap). */
function gap(s: Shape, t: Shape): number {
  if (s.kind === "seg" && t.kind === "seg") return segSeg(s.a, s.b, t.a, t.b) - s.r - t.r
  if (s.kind === "rect" && t.kind === "rect") {
    const dx = Math.max(0, Math.abs(s.cx - t.cx) - s.hw - t.hw)
    const dy = Math.max(0, Math.abs(s.cy - t.cy) - s.hh - t.hh)
    return Math.hypot(dx, dy)
  }
  const seg = (s.kind === "seg" ? s : t) as Extract<Shape, { kind: "seg" }>
  const rect = (s.kind === "rect" ? s : t) as Extract<Shape, { kind: "rect" }>
  if (inRect(seg.a, rect) || inRect(seg.b, rect)) return -seg.r
  const c = rectCorners(rect)
  let d = Infinity
  for (let i = 0; i < 4; i++) d = Math.min(d, segSeg(seg.a, seg.b, c[i]!, c[(i + 1) % 4]!))
  return d - seg.r
}

function bbox(s: Shape): [number, number, number, number] {
  if (s.kind === "rect") return [s.cx - s.hw, s.cy - s.hh, s.cx + s.hw, s.cy + s.hh]
  return [Math.min(s.a.x, s.b.x) - s.r, Math.min(s.a.y, s.b.y) - s.r, Math.max(s.a.x, s.b.x) + s.r, Math.max(s.a.y, s.b.y) + s.r]
}

const centre = (s: Shape): Pt => (s.kind === "rect" ? { x: s.cx, y: s.cy } : { x: (s.a.x + s.b.x) / 2, y: (s.a.y + s.b.y) / 2 })

interface Extracted {
  shapes: Shape[]
  /** One entry per pin that has copper: its net key, label and the shapes that are its pad */
  pins: { net: string; label: string; shapeIndexes: number[] }[]
  netName: (key: string) => string
  /** Net keys that have a copper pour, per layer */
  pours: { net: string; layer: string }[]
}

function extract(circuitJson: any[]): Extracted {
  const of = (t: string) => circuitJson.filter((e) => e.type === t)
  const pinShapes = new Map<string, { net: string; label: string; shapeIndexes: number[] }>()
  const notePin = (pcbPortId: string | undefined, net: string, label: string, index: number) => {
    if (!pcbPortId) return
    const e = pinShapes.get(pcbPortId) ?? { net, label, shapeIndexes: [] }
    e.shapeIndexes.push(index)
    pinShapes.set(pcbPortId, e)
  }
  const srcPort = new Map(of("source_port").map((p) => [p.source_port_id, p]))
  const srcComp = new Map(of("source_component").map((c) => [c.source_component_id, c]))
  const pcbPort = new Map(of("pcb_port").map((p) => [p.pcb_port_id, p]))
  const srcNet = new Map(of("source_net").map((n) => [n.subcircuit_connectivity_map_key, n.name]))

  /** Net key of a PCB port: the connectivity group, or a unique id for an unconnected pin. */
  const netOfPort = (pcbPortId: string | undefined): string | undefined => {
    const sp = srcPort.get(pcbPort.get(pcbPortId ?? "")?.source_port_id)
    if (!sp) return undefined
    return sp.subcircuit_connectivity_map_key ?? `nc:${sp.source_port_id}`
  }
  const pinLabel = (pcbPortId: string | undefined): string => {
    const sp = srcPort.get(pcbPort.get(pcbPortId ?? "")?.source_port_id)
    return sp ? `${srcComp.get(sp.source_component_id)?.name ?? "?"}.${sp.name}` : "pad"
  }
  const netName = (key: string) => srcNet.get(key) ?? (key.startsWith("nc:") ? "unconnected pin" : "net")

  const shapes: Shape[] = []

  for (const p of of("pcb_smtpad")) {
    const net = netOfPort(p.pcb_port_id) ?? `pad:${p.pcb_smtpad_id}`
    const layer = p.layer ?? "top"
    const label = `${pinLabel(p.pcb_port_id)} pad`
    if (p.shape === "circle" && p.radius) {
      shapes.push({ kind: "seg", a: { x: p.x, y: p.y }, b: { x: p.x, y: p.y }, r: p.radius, net, layer, label })
      notePin(p.pcb_port_id, net, pinLabel(p.pcb_port_id), shapes.length - 1)
    } else if (typeof p.width === "number" && typeof p.height === "number") {
      const rot = ((Math.round(Number(p.ccw_rotation ?? 0)) % 180) + 180) % 180
      if (rot === 0 || rot === 90) {
        const [w, h] = rot === 90 ? [p.height, p.width] : [p.width, p.height]
        shapes.push({ kind: "rect", cx: p.x, cy: p.y, hw: w / 2, hh: h / 2, net, layer, label })
      } else {
        // Any other angle: a capsule along the pad's long axis. It lies inside the real pad, so only the corner slivers are missed.
        shapes.push(capsule(p.x, p.y, p.width, p.height, Number(p.ccw_rotation), { net, layer, label }))
      }
      notePin(p.pcb_port_id, net, pinLabel(p.pcb_port_id), shapes.length - 1)
    }
  }
  for (const h of of("pcb_plated_hole")) {
    const net = netOfPort(h.pcb_port_id) ?? `hole:${h.pcb_plated_hole_id}`
    const w = h.outer_diameter ?? h.outer_width ?? h.rect_pad_width
    const ht = h.outer_diameter ?? h.outer_height ?? h.rect_pad_height
    if (typeof w !== "number" || typeof ht !== "number") continue
    // Round and slotted (pill) pads are exactly a capsule; rectangular pads are a rectangle at 0 / 90 degrees.
    const hrot = ((Math.round(Number(h.ccw_rotation ?? 0)) % 180) + 180) % 180
    const rounded = h.shape === "circle" || h.shape === "pill"
    for (const layer of ["top", "bottom"]) {
      const rest = { net, layer, label: `${pinLabel(h.pcb_port_id)} hole`, through: `hole:${h.pcb_plated_hole_id}` }
      if (rounded || (hrot !== 0 && hrot !== 90)) shapes.push(capsule(h.x, h.y, w, ht, Number(h.ccw_rotation ?? 0), rest))
      else {
        const [pw, ph] = hrot === 90 ? [ht, w] : [w, ht]
        shapes.push({ kind: "rect", cx: h.x, cy: h.y, hw: pw / 2, hh: ph / 2, ...rest })
      }
      notePin(h.pcb_port_id, net, pinLabel(h.pcb_port_id), shapes.length - 1)
    }
  }
  for (const v of of("pcb_via")) {
    if (typeof v.outer_diameter !== "number") continue
    const net = v.subcircuit_connectivity_map_key ?? `via:${v.pcb_via_id}`
    for (const layer of v.layers ?? ["top", "bottom"])
      shapes.push({ kind: "seg", a: { x: v.x, y: v.y }, b: { x: v.x, y: v.y }, r: v.outer_diameter / 2, net, layer, label: "via", through: `via:${v.pcb_via_id}` })
  }
  for (const t of of("pcb_trace")) {
    const route: any[] = t.route ?? []
    const portId = route.map((pt) => pt.start_pcb_port_id ?? pt.end_pcb_port_id).find(Boolean)
    const net = netOfPort(portId) ?? `trace:${t.pcb_trace_id}`
    for (let i = 1; i < route.length; i++) {
      const a = route[i - 1]
      const b = route[i]
      if (a.route_type !== "wire" || b.route_type !== "wire" || a.layer !== b.layer) continue
      const w = Math.min(a.width ?? b.width ?? 0.15, b.width ?? a.width ?? 0.15)
      shapes.push({ kind: "seg", a: { x: a.x, y: a.y }, b: { x: b.x, y: b.y }, r: w / 2, net, layer: b.layer, label: `${netName(net)} trace` })
    }
  }

  const pours = of("pcb_copper_pour")
    .map((p) => ({ net: p.subcircuit_connectivity_map_key ?? (p.source_net_id ? [...srcNet.entries()].find(([, name]) => name === of("source_net").find((n) => n.source_net_id === p.source_net_id)?.name)?.[0] : undefined), layer: p.layer ?? "top" }))
    .filter((p): p is { net: string; layer: string } => Boolean(p.net))
  return { shapes, pins: [...pinShapes.values()], netName, pours }
}

export function clearanceCheck(circuitJson: any[], limitMm: number): ClearanceResult {
  const { shapes } = extract(circuitJson)

  // Sweep along x with bounding boxes so only nearby shapes are compared.
  const margin = Math.max(limitMm, 0.2)
  const items = shapes.map((s) => ({ s, bb: bbox(s) })).sort((p, q) => p.bb[0] - q.bb[0])
  let minGap = Infinity
  let pairs = 0
  const worst = new Map<string, ClearanceViolation>()
  for (let i = 0; i < items.length; i++) {
    const A = items[i]!
    for (let j = i + 1; j < items.length; j++) {
      const B = items[j]!
      if (B.bb[0] > A.bb[2] + margin) break
      if (A.s.layer !== B.s.layer || A.s.net === B.s.net) continue
      if (B.bb[1] > A.bb[3] + margin || B.bb[3] < A.bb[1] - margin) continue
      pairs++
      const g = gap(A.s, B.s)
      if (g < minGap) minGap = g
      if (g < limitMm - 1e-6) {
        // One entry per pair of nets per layer: the tightest spot.
        const key = [A.s.layer, ...[A.s.net, B.s.net].sort()].join("|")
        const prev = worst.get(key)
        if (!prev || g < prev.gapMm) {
          const ca = centre(A.s)
          const cb = centre(B.s)
          worst.set(key, {
            gapMm: Math.round(Math.max(g, 0) * 1000) / 1000,
            layer: A.s.layer,
            a: A.s.label,
            b: B.s.label,
            at: { x: Math.round(((ca.x + cb.x) / 2) * 100) / 100, y: Math.round(((ca.y + cb.y) / 2) * 100) / 100 },
          })
        }
      }
    }
  }
  return {
    minGapMm: Number.isFinite(minGap) ? Math.round(Math.max(minGap, 0) * 1000) / 1000 : null,
    pairsChecked: pairs,
    violations: [...worst.values()].sort((p, q) => p.gapMm - q.gapMm),
  }
}


// ---- layout vs netlist ---------------------------------------------------------

export interface ConnectivityResult {
  netsChecked: number
  /** Nets whose pins are not all joined by copper, with the pins that are cut off from the largest group */
  opens: { net: string; isolatedPins: string[]; groups: number }[]
}

/**
 * Rebuild electrical connectivity from copper geometry (touching shapes on a layer are one
 * conductor; vias and plated holes join layers) and compare it with the netlist: every pin of a
 * net must end up in the same conductor. Shorts between nets are the spacing check's job.
 *
 * A copper pour is taken to join all copper of its own net on its layer.
 */
export function connectivityCheck(circuitJson: any[]): ConnectivityResult {
  const { shapes, pins, netName, pours } = extract(circuitJson)
  const parent = shapes.map((_, i) => i)
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i]!)))
  const union = (i: number, j: number) => {
    const a = find(i)
    const b = find(j)
    if (a !== b) parent[a] = b
  }
  // same barrel through the board
  const barrels = new Map<string, number>()
  shapes.forEach((s, i) => {
    if (!s.through) return
    const first = barrels.get(s.through)
    if (first === undefined) barrels.set(s.through, i)
    else union(first, i)
  })
  // touching copper of the same net on the same layer
  const items = shapes.map((s, i) => ({ s, i, bb: bbox(s) })).sort((p, q) => p.bb[0] - q.bb[0])
  const TOUCH = 0.005
  for (let a = 0; a < items.length; a++) {
    const A = items[a]!
    for (let b = a + 1; b < items.length; b++) {
      const B = items[b]!
      if (B.bb[0] > A.bb[2] + TOUCH) break
      if (A.s.layer !== B.s.layer || A.s.net !== B.s.net) continue
      if (B.bb[1] > A.bb[3] + TOUCH || B.bb[3] < A.bb[1] - TOUCH) continue
      if (gap(A.s, B.s) <= TOUCH) union(A.i, B.i)
    }
  }
  // a pour joins its net's copper on its layer
  for (const pour of pours) {
    let first = -1
    shapes.forEach((s, i) => {
      if (s.net !== pour.net || s.layer !== pour.layer) return
      if (first === -1) first = i
      else union(first, i)
    })
  }

  const byNet = new Map<string, { label: string; root: number }[]>()
  for (const pin of pins) {
    if (pin.net.startsWith("nc:") || !pin.shapeIndexes.length) continue
    for (let k = 1; k < pin.shapeIndexes.length; k++) union(pin.shapeIndexes[0]!, pin.shapeIndexes[k]!)
    const list = byNet.get(pin.net) ?? []
    list.push({ label: pin.label, root: pin.shapeIndexes[0]! })
    byNet.set(pin.net, list)
  }
  const opens: ConnectivityResult["opens"] = []
  let netsChecked = 0
  for (const [net, list] of byNet) {
    if (list.length < 2) continue
    netsChecked++
    const groups = new Map<number, string[]>()
    for (const p of list) {
      const r = find(p.root)
      groups.set(r, [...(groups.get(r) ?? []), p.label])
    }
    if (groups.size <= 1) continue
    const sorted = [...groups.values()].sort((a, b) => b.length - a.length)
    opens.push({ net: netName(net), isolatedPins: sorted.slice(1).flat(), groups: groups.size })
  }
  return { netsChecked, opens }
}
